//! Single-process Verus spec projected from TLA+ module `RaftClean`.
//!
//! Generated by `verus-transpile clean-tla`. Do not edit by hand: the
//! clean-subset spec it came from is the source of truth. Only this header is
//! written by a human; `tests/corpus/scripts/refresh_goldens.sh` replaces the
//! `verus!` block and leaves the prose alone.
//!
//! **Tier 2.** Raft is the first case whose *data* is structured rather than
//! scalar, and every defect it exposed was of that one kind — the projection
//! knowing a value's shape. What it forced, in the order the translator found
//! it (see `rewrite.md` for the fidelity claims):
//!
//! - **`LLogEntry`.** `LogEntry == [term: Term, value: Value]` is a record set
//!   with no tag field, so it is data rather than a message. It is also
//!   declared *before* `Message`, which is how it caught the message pass
//!   stopping at the first record set it found — Raft briefly projected to a
//!   spec with no messages at all.
//! - **`Seq<LLogEntry>` and the 1-indexing rule.** `log[i]` is a sequence, and
//!   `xlog[Len(xlog)]` is its last element. TLA+ counts from 1 and Verus's
//!   `Seq` from 0, so the index loses one — which is only sound because the
//!   projection knows the type. `nextIndex[j]` is a *map* lookup and must not
//!   lose one; the two are indistinguishable without types.
//! - **`LLastTerm` returns `int`.** Its body is a conditional over terms. A
//!   helper's result type is read off the TLA+ body: the emitted text
//!   `if xlog.len() == 0 { .. }` contains `==` and reads as a predicate.
//! - **`LStateKind`.** The variable really is called `state`, and `LState` is
//!   already the projected state struct. The labels are named
//!   (`Follower == "follower"`), so the enum is found only by following the
//!   0-ary operators — otherwise `state` becomes an `int` that string literals
//!   are assigned to.
//! - **`src`.** Raft addresses with `msource`/`mdest`. Routing does not survive
//!   into the payload: the sender is the dispatch's `src` and the destination
//!   is this node by construction.
//! - **Whole variants.** `AEResp(i, j, term, TRUE, 0)` fills two fields with
//!   literals. A construction must fill exactly the fields its variant
//!   declares, or it names a variant it does not build.
//!
//! **What is not here.** `LNext` has no `Timeout`-style environment action and
//! no leader-completeness invariant: `clean.tla` is a slice (elections,
//! one-entry append, commit index) and the log-conflict truncation is out of
//! scope. The `Consistency`-style properties of the original rest on history
//! variables that C3 deletes.

use vstd::prelude::*;

verus! {
    pub enum LStateKind {
        Follower,
        Candidate,
        Leader,
    }

    pub struct LLogEntry {
        pub term: int,
        pub value: int,
    }

    /// Wire messages. Routing lives on the packet, not in the payload.
    pub enum LMessage {
        Rvq { mterm: int, mlast_log_term: int, mlast_log_index: int },
        Rvp { mterm: int, mvote_granted: bool },
        Aeq { mterm: int, mprev_log_index: int, mprev_log_term: int, mentries: Seq<LLogEntry>, mcommit_index: int },
        Aep { mterm: int, msuccess: bool, mmatch_index: int },
    }

    /// A message addressed to a peer.
    pub struct LPacket {
        pub dst: int,
        pub msg: LMessage,
    }

    /// This node's state.
    pub struct LState {
        pub current_term: int,
        pub state: LStateKind,
        pub voted_for: int,
        pub log: Seq<LLogEntry>,
        pub commit_index: int,
        pub votes_responded: Set<int>,
        pub votes_granted: Set<int>,
        pub next_index: Map<int, int>,
        pub match_index: Map<int, int>,
    }

    /// Protocol constants, including this node's own identity.
    pub struct LConstants {
        pub server: Set<int>,
        pub value: Set<int>,
        pub max_term: int,
        pub max_log_len: int,
        pub node_id: int,
    }

    pub open spec fn LIsMajority(c: LConstants, s_arg: Set<int>) -> bool {
        (s_arg.len() as int) * 2 > (c.server.len() as int)
    }

    pub open spec fn LLastTerm(c: LConstants, xlog: Seq<LLogEntry>) -> int {
        if (xlog.len() as int) == 0 { 0 } else { xlog[(xlog.len() as int) - 1].term }
    }

    pub open spec fn LInit(s: LState, c: LConstants) -> bool {
        &&& s.current_term == 1
        &&& s.state is Follower
        &&& s.voted_for == 0
        &&& s.log == Seq::<LLogEntry>::empty()
        &&& s.commit_index == 0
        &&& s.votes_responded == Set::<int>::empty()
        &&& s.votes_granted == Set::<int>::empty()
        &&& s.next_index == Map::new(c.server, |j: int| 1int)
        &&& s.match_index == Map::new(c.server, |j: int| 0int)
    }

    pub open spec fn LRestart(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s_.state is Follower
        &&& s_.votes_responded == Set::<int>::empty()
        &&& s_.votes_granted == Set::<int>::empty()
        &&& s_.next_index == Map::new(c.server, |j: int| 1int)
        &&& s_.match_index == Map::new(c.server, |j: int| 0int)
        &&& s_.commit_index == 0
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.current_term == s.current_term
        &&& s_.voted_for == s.voted_for
        &&& s_.log == s.log
    }

    pub open spec fn LTimeout(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.state is Follower || s.state is Candidate
        &&& s.current_term < c.max_term
        &&& s_.state is Candidate
        &&& s_.current_term == s.current_term + 1
        &&& s_.voted_for == 0
        &&& s_.votes_responded == Set::<int>::empty()
        &&& s_.votes_granted == Set::<int>::empty()
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.log == s.log
        &&& s_.commit_index == s.commit_index
        &&& s_.next_index == s.next_index
        &&& s_.match_index == s.match_index
    }

    pub open spec fn LRequestVote(
        s: LState,
        s_: LState,
        c: LConstants,
        j: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.state is Candidate
        &&& !s.votes_responded.contains(j)
        &&& sent_packets == set![LPacket { dst: j, msg: LMessage::Rvq { mterm: s.current_term, mlast_log_term: LLastTerm(c, s.log), mlast_log_index: (s.log.len() as int) } }]
        &&& s_.current_term == s.current_term
        &&& s_.state == s.state
        &&& s_.voted_for == s.voted_for
        &&& s_.log == s.log
        &&& s_.commit_index == s.commit_index
        &&& s_.votes_responded == s.votes_responded
        &&& s_.votes_granted == s.votes_granted
        &&& s_.next_index == s.next_index
        &&& s_.match_index == s.match_index
    }

    pub open spec fn LBecomeLeader(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.state is Candidate
        &&& LIsMajority(c, s.votes_granted)
        &&& s_.state is Leader
        &&& s_.next_index == Map::new(c.server, |j: int| (s.log.len() as int) + 1)
        &&& s_.match_index == Map::new(c.server, |j: int| 0int)
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.current_term == s.current_term
        &&& s_.voted_for == s.voted_for
        &&& s_.log == s.log
        &&& s_.commit_index == s.commit_index
        &&& s_.votes_responded == s.votes_responded
        &&& s_.votes_granted == s.votes_granted
    }

    pub open spec fn LClientRequest(
        s: LState,
        s_: LState,
        c: LConstants,
        v: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& s.state is Leader
        &&& (s.log.len() as int) < c.max_log_len
        &&& s_.log == s.log.push(LLogEntry { term: s.current_term, value: v })
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.current_term == s.current_term
        &&& s_.state == s.state
        &&& s_.voted_for == s.voted_for
        &&& s_.commit_index == s.commit_index
        &&& s_.votes_responded == s.votes_responded
        &&& s_.votes_granted == s.votes_granted
        &&& s_.next_index == s.next_index
        &&& s_.match_index == s.match_index
    }

    pub open spec fn LAppendEntries(
        s: LState,
        s_: LState,
        c: LConstants,
        j: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& c.node_id != j
        &&& s.state is Leader
        &&& sent_packets == set![LPacket { dst: j, msg: LMessage::Aeq { mterm: s.current_term, mprev_log_index: s.next_index[j] - 1, mprev_log_term: if s.next_index[j] - 1 > 0 { s.log[s.next_index[j] - 1 - 1].term } else { 0 }, mentries: s.log.subrange(s.next_index[j] - 1, if (s.log.len() as int) < s.next_index[j] { (s.log.len() as int) } else { s.next_index[j] }), mcommit_index: if s.commit_index < s.next_index[j] { s.commit_index } else { s.next_index[j] } } }]
        &&& s_.current_term == s.current_term
        &&& s_.state == s.state
        &&& s_.voted_for == s.voted_for
        &&& s_.log == s.log
        &&& s_.commit_index == s.commit_index
        &&& s_.votes_responded == s.votes_responded
        &&& s_.votes_granted == s.votes_granted
        &&& s_.next_index == s.next_index
        &&& s_.match_index == s.match_index
    }

    pub open spec fn LHandleRequestVoteRequest(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mterm: int,
        mlast_log_term: int,
        mlast_log_index: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mterm <= s.current_term
        &&& s_.voted_for == if mterm == s.current_term && (mlast_log_term > LLastTerm(c, s.log) || mlast_log_term == LLastTerm(c, s.log) && mlast_log_index >= (s.log.len() as int)) && set![0, src].contains(s.voted_for) { src } else { s.voted_for }
        &&& sent_packets == if mterm == s.current_term && (mlast_log_term > LLastTerm(c, s.log) || mlast_log_term == LLastTerm(c, s.log) && mlast_log_index >= (s.log.len() as int)) && set![0, src].contains(s.voted_for) { set![LPacket { dst: src, msg: LMessage::Rvp { mterm: s.current_term, mvote_granted: true } }] } else { set![LPacket { dst: src, msg: LMessage::Rvp { mterm: s.current_term, mvote_granted: false } }] }
        &&& s_.current_term == s.current_term
        &&& s_.state == s.state
        &&& s_.log == s.log
        &&& s_.commit_index == s.commit_index
        &&& s_.votes_responded == s.votes_responded
        &&& s_.votes_granted == s.votes_granted
        &&& s_.next_index == s.next_index
        &&& s_.match_index == s.match_index
    }

    pub open spec fn LHandleRequestVoteResponse(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mterm: int,
        mvote_granted: bool,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mterm == s.current_term
        &&& s_.votes_responded == s.votes_responded.union(set![src])
        &&& s_.votes_granted == if mvote_granted { s.votes_granted.union(set![src]) } else { s.votes_granted }
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.current_term == s.current_term
        &&& s_.state == s.state
        &&& s_.voted_for == s.voted_for
        &&& s_.log == s.log
        &&& s_.commit_index == s.commit_index
        &&& s_.next_index == s.next_index
        &&& s_.match_index == s.match_index
    }

    pub open spec fn LHandleAppendEntriesRequest(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mterm: int,
        mprev_log_index: int,
        mprev_log_term: int,
        mentries: Seq<LLogEntry>,
        mcommit_index: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mterm <= s.current_term
        &&& s_.commit_index == if mterm == s.current_term && s.state is Follower && (mprev_log_index == 0 || mprev_log_index > 0 && mprev_log_index <= (s.log.len() as int)) { mcommit_index } else { s.commit_index }
        &&& s_.log == if mterm == s.current_term && s.state is Follower && (mprev_log_index == 0 || mprev_log_index > 0 && mprev_log_index <= (s.log.len() as int)) { if mentries == Seq::empty() { s.log } else { s.log.push(mentries[0]) } } else { s.log }
        &&& sent_packets == if mterm == s.current_term && s.state is Follower && (mprev_log_index == 0 || mprev_log_index > 0 && mprev_log_index <= (s.log.len() as int)) { set![LPacket { dst: src, msg: LMessage::Aep { mterm: s.current_term, msuccess: true, mmatch_index: mprev_log_index + (mentries.len() as int) } }] } else { set![LPacket { dst: src, msg: LMessage::Aep { mterm: s.current_term, msuccess: false, mmatch_index: 0 } }] }
        &&& s_.current_term == s.current_term
        &&& s_.state == s.state
        &&& s_.voted_for == s.voted_for
        &&& s_.votes_responded == s.votes_responded
        &&& s_.votes_granted == s.votes_granted
        &&& s_.next_index == s.next_index
        &&& s_.match_index == s.match_index
    }

    pub open spec fn LHandleAppendEntriesResponse(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        mterm: int,
        msuccess: bool,
        mmatch_index: int,
        sent_packets: Set<LPacket>,
    ) -> bool {
        &&& mterm == s.current_term
        &&& s_.next_index == if msuccess { s.next_index.insert(src, mmatch_index + 1) } else { s.next_index.insert(src, if s.next_index[src] > 1 { s.next_index[src] - 1 } else { 1 }) }
        &&& s_.match_index == if msuccess { s.match_index.insert(src, mmatch_index) } else { s.match_index }
        &&& sent_packets == Set::<LPacket>::empty()
        &&& s_.current_term == s.current_term
        &&& s_.state == s.state
        &&& s_.voted_for == s.voted_for
        &&& s_.log == s.log
        &&& s_.commit_index == s.commit_index
        &&& s_.votes_responded == s.votes_responded
        &&& s_.votes_granted == s.votes_granted
    }

    /// Dispatch on the received message. Delivery and the tag are the
    /// framework's; each handler states only its own conditions.
    pub open spec fn LHandleMessage(
        s: LState,
        s_: LState,
        c: LConstants,
        src: int,
        msg: LMessage,
        sent_packets: Set<LPacket>,
    ) -> bool {
        match msg {
            LMessage::Rvq { mterm, mlast_log_term, mlast_log_index } =>
                LHandleRequestVoteRequest(s, s_, c, src, mterm, mlast_log_term, mlast_log_index, sent_packets),
            LMessage::Rvp { mterm, mvote_granted } =>
                LHandleRequestVoteResponse(s, s_, c, src, mterm, mvote_granted, sent_packets),
            LMessage::Aeq { mterm, mprev_log_index, mprev_log_term, mentries, mcommit_index } =>
                LHandleAppendEntriesRequest(s, s_, c, src, mterm, mprev_log_index, mprev_log_term, mentries, mcommit_index, sent_packets),
            LMessage::Aep { mterm, msuccess, mmatch_index } =>
                LHandleAppendEntriesResponse(s, s_, c, src, mterm, msuccess, mmatch_index, sent_packets),
        }
    }

    pub open spec fn LNext(
        s: LState,
        s_: LState,
        c: LConstants,
        sent_packets: Set<LPacket>,
    ) -> bool {
        ||| LRestart(s, s_, c, sent_packets)
        ||| LTimeout(s, s_, c, sent_packets)
        ||| (exists|j: int|
                c.server.contains(j) && LRequestVote(s, s_, c, j, sent_packets))
        ||| LBecomeLeader(s, s_, c, sent_packets)
        ||| (exists|v: int|
                c.value.contains(v) && LClientRequest(s, s_, c, v, sent_packets))
        ||| (exists|j: int|
                c.server.contains(j) && LAppendEntries(s, s_, c, j, sent_packets))
        ||| (exists|src: int, msg: LMessage|
                LHandleMessage(s, s_, c, src, msg, sent_packets))
    }
}
